steps.action:
curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "{
      projects(filter: {name: {eq: \"Checkout Redesign\"}}) {
        nodes {
          id
          name
          documents {
            nodes {
              id
              title
              lastEditedAt
              user {
                id
                name
              }
            }
          }
        }
      }
      users(filter: {name: {contains: \"Leo Park\"}}) {
        nodes {
          id
          name
        }
      }
    }"
  }'

